export const CAST={nico:{color:'#2ac9b4',accent:'#e4fff5'},lia:{color:'#ac76e2',accent:'#f3ddff',pony:true},sol:{color:'#ec8967',accent:'#ffecda'},courier:{color:'#5678a1',accent:'#e3ebed'},ari:{color:'#d69b4d',accent:'#fff1c8'},gui:{color:'#659edc',accent:'#e8f3ff',kid:true}};
