const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
// Fixed two-bone IK in the actor's sagittal plane; the bend side never changes mid-action.
export function solve(a,target,l1,l2,side=1){const dx=target[0]-a[0],dy=target[1]-a[1],len=Math.hypot(dx,dy),d=clamp(len,.005,l1+l2-.003),b=[a[0]+dx/(len||1)*d,a[1]+dy/(len||1)*d,target[2]],ang=Math.atan2(dy,dx)-side*Math.acos(clamp((l1*l1+d*d-l2*l2)/(2*l1*d),-1,1));return {end:b,elbow:[a[0]+Math.cos(ang)*l1,a[1]+Math.sin(ang)*l1,a[2]]};}
