   if(seated){footX=.36;footY=.065;}
   else if(moving){if(q<stance)footX=stride/2-q/stance*stride;else{const u=(q-stance)/(1-stance);footX=-stride/2+stride*(u*u*(3-2*u));footY+=(o.run?.19:.08)*Math.sin(Math.PI*u);}}
