   const shoulder=[sh[0],sh[1],i?-.19:.19];const swing=moving?Math.sin((phase+i*.5)*Math.PI*2):0;let hand=o.run?[lean+.10-.35*swing,hip+.21-.12*swing,shoulder[2]]:[lean+.08+.12*swing,hip-.09,shoulder[2]];
